module gemm_ctrl_fsm #(
  parameter int M_FIXED = 8,
  parameter int N_FIXED = 8,
  parameter int K_FIXED = 32
) (
  input  logic clk,
  input  logic rst_n,
  input  logic cmd_hs,
  input  logic cmd_payload,
  input  logic a_hs,
  input  logic b_hs,
  input  logic bias_hs,
  input  logic compute_done,
  input  logic out_hs,
  output logic state_load_a,
  output logic state_load_b,
  output logic state_load_bias,
  output logic state_compute,
  output logic state_output,
  output logic cmd_ready,
  output logic a_ready,
  output logic b_ready,
  output logic bias_ready,
  output logic busy,
  output logic completion,
  output logic error
);
  localparam int A_COUNT    = M_FIXED*K_FIXED;
  localparam int B_COUNT    = K_FIXED*N_FIXED;
  localparam int BIAS_COUNT = N_FIXED;
  localparam int C_COUNT    = M_FIXED*N_FIXED;

  localparam int AW_A    = (A_COUNT    <= 1) ? 1 : $clog2(A_COUNT+1);
  localparam int AW_B    = (B_COUNT    <= 1) ? 1 : $clog2(B_COUNT+1);
  localparam int AW_BIAS = (BIAS_COUNT <= 1) ? 1 : $clog2(BIAS_COUNT+1);
  localparam int AW_C    = (C_COUNT    <= 1) ? 1 : $clog2(C_COUNT+1);

  typedef enum logic [2:0] {
    ST_IDLE      = 3'd0,
    ST_LOAD_A    = 3'd1,
    ST_LOAD_B    = 3'd2,
    ST_LOAD_BIAS = 3'd3,
    ST_COMPUTE   = 3'd4,
    ST_OUTPUT    = 3'd5,
    ST_DONE      = 3'd6
  } state_t;

  state_t state_q, state_d;
  logic [AW_A-1:0]    a_count_q;
  logic [AW_B-1:0]    b_count_q;
  logic [AW_BIAS-1:0] bias_count_q;
  logic [AW_C-1:0]    out_count_q;

  always_comb begin
    state_load_a    = (state_q == ST_LOAD_A);
    state_load_b    = (state_q == ST_LOAD_B);
    state_load_bias = (state_q == ST_LOAD_BIAS);
    state_compute   = (state_q == ST_COMPUTE);
    state_output    = (state_q == ST_OUTPUT);

    cmd_ready  = rst_n && (state_q == ST_IDLE);
    a_ready    = rst_n && (state_q == ST_LOAD_A);
    b_ready    = rst_n && (state_q == ST_LOAD_B);
    bias_ready = rst_n && (state_q == ST_LOAD_BIAS);

    state_d = state_q;
    unique case (state_q)
      ST_IDLE:      if (cmd_hs && (cmd_payload == 1'b1)) state_d = ST_LOAD_A;
      ST_LOAD_A:    if (a_hs    && (a_count_q    == A_COUNT-1)) state_d = ST_LOAD_B;
      ST_LOAD_B:    if (b_hs    && (b_count_q    == B_COUNT-1)) state_d = ST_LOAD_BIAS;
      ST_LOAD_BIAS: if (bias_hs && (bias_count_q == BIAS_COUNT-1)) state_d = ST_COMPUTE;
      ST_COMPUTE:   if (compute_done) state_d = ST_OUTPUT;
      ST_OUTPUT:    if (out_hs && (out_count_q == C_COUNT-1)) state_d = ST_DONE;
      ST_DONE:      state_d = ST_IDLE;
      default:      state_d = ST_IDLE;
    endcase
  end

  always_ff @(posedge clk) begin
    if (!rst_n) begin
      state_q      <= ST_IDLE;
      a_count_q    <= '0;
      b_count_q    <= '0;
      bias_count_q <= '0;
      out_count_q  <= '0;
      busy         <= 1'b0;
      completion   <= 1'b0;
      error        <= 1'b0;
    end else begin
      state_q <= state_d;
      completion <= 1'b0;
      error <= 1'b0;

      if ((state_q == ST_IDLE) && cmd_hs && (cmd_payload == 1'b1)) busy <= 1'b1;
      if ((state_q == ST_OUTPUT) && out_hs && (out_count_q == C_COUNT-1)) busy <= 1'b0;
      if (state_q == ST_DONE) completion <= 1'b1;

      if (cmd_hs && ((state_q != ST_IDLE) || (cmd_payload != 1'b1))) error <= 1'b1;
      if (a_hs    && (state_q != ST_LOAD_A))    error <= 1'b1;
      if (b_hs    && (state_q != ST_LOAD_B))    error <= 1'b1;
      if (bias_hs && (state_q != ST_LOAD_BIAS)) error <= 1'b1;

      if (state_q != ST_LOAD_A) a_count_q <= '0;
      else if (a_hs) a_count_q <= a_count_q + 1'b1;

      if (state_q != ST_LOAD_B) b_count_q <= '0;
      else if (b_hs) b_count_q <= b_count_q + 1'b1;

      if (state_q != ST_LOAD_BIAS) bias_count_q <= '0;
      else if (bias_hs) bias_count_q <= bias_count_q + 1'b1;

      if (state_q != ST_OUTPUT) out_count_q <= '0;
      else if (out_hs) out_count_q <= out_count_q + 1'b1;
    end
  end
endmodule

module operand_buffer_bank #(
  parameter int M_FIXED = 8,
  parameter int N_FIXED = 8,
  parameter int K_FIXED = 32
) (
  input  logic                  clk,
  input  logic                  we_a,
  input  logic [7:0]            waddr_a,
  input  logic signed [7:0]     wdata_a,
  input  logic                  we_b,
  input  logic [7:0]            waddr_b,
  input  logic signed [7:0]     wdata_b,
  input  logic                  we_bias,
  input  logic [2:0]            waddr_bias,
  input  logic signed [31:0]    wdata_bias,
  input  logic [7:0]            raddr_a,
  output logic signed [7:0]     rdata_a,
  input  logic [7:0]            raddr_b,
  output logic signed [7:0]     rdata_b,
  input  logic [2:0]            raddr_bias,
  output logic signed [31:0]    rdata_bias,
  input  logic                  we_c,
  input  logic [5:0]            waddr_c,
  input  logic signed [31:0]    wdata_c,
  input  logic [5:0]            raddr_c,
  output logic signed [31:0]    rdata_c
);
  localparam int A_COUNT    = M_FIXED*K_FIXED;
  localparam int B_COUNT    = K_FIXED*N_FIXED;
  localparam int BIAS_COUNT = N_FIXED;
  localparam int C_COUNT    = M_FIXED*N_FIXED;

  logic signed [7:0]  a_buf [0:A_COUNT-1];
  logic signed [7:0]  b_buf [0:B_COUNT-1];
  logic signed [31:0] bias_buf [0:BIAS_COUNT-1];
  logic signed [31:0] c_buf [0:C_COUNT-1];

  always_ff @(posedge clk) begin
    if (we_a) a_buf[waddr_a] <= wdata_a;
    if (we_b) b_buf[waddr_b] <= wdata_b;
    if (we_bias) bias_buf[waddr_bias] <= wdata_bias;
    if (we_c) c_buf[waddr_c] <= wdata_c;

    rdata_a    <= a_buf[raddr_a];
    rdata_b    <= b_buf[raddr_b];
    rdata_bias <= bias_buf[raddr_bias];
    rdata_c    <= c_buf[raddr_c];
  end
endmodule

module mac_sequencer #(
  parameter int M_FIXED = 8,
  parameter int N_FIXED = 8,
  parameter int K_FIXED = 32
) (
  input  logic clk,
  input  logic rst_n,
  input  logic enable_compute,
  output logic [7:0] raddr_a,
  input  logic signed [7:0] rdata_a,
  output logic [7:0] raddr_b,
  input  logic signed [7:0] rdata_b,
  output logic [2:0] raddr_bias,
  input  logic signed [31:0] rdata_bias,
  output logic we_c,
  output logic [5:0] waddr_c,
  output logic signed [31:0] wdata_c,
  output logic compute_done
);
  typedef enum logic [1:0] {PH_BIAS_ISSUE=2'd0, PH_BIAS_CAPTURE=2'd1, PH_MAC_ISSUE=2'd2, PH_MAC_UPDATE=2'd3} ph_t;
  ph_t ph_q;

  logic [2:0] i_q, j_q;
  logic [5:0] k_q;
  logic signed [31:0] acc_q;
  logic signed [7:0] a_hold_q, b_hold_q;

  logic [7:0] a_addr_calc, b_addr_calc;
  logic [5:0] c_addr_calc;
  logic signed [15:0] prod16;
  logic signed [31:0] prod32;
  logic signed [31:0] sum32;

  always_comb begin
    a_addr_calc = (i_q * K_FIXED) + k_q;
    b_addr_calc = (k_q * N_FIXED) + j_q;
    c_addr_calc = (i_q * N_FIXED) + j_q;
    prod16 = a_hold_q * b_hold_q;
    prod32 = {{16{prod16[15]}}, prod16};
    sum32 = acc_q + prod32;
  end

  always_ff @(posedge clk) begin
    if (!rst_n) begin
      ph_q <= PH_BIAS_ISSUE;
      i_q <= '0;
      j_q <= '0;
      k_q <= '0;
      acc_q <= '0;
      a_hold_q <= '0;
      b_hold_q <= '0;
      raddr_a <= '0;
      raddr_b <= '0;
      raddr_bias <= '0;
      we_c <= 1'b0;
      waddr_c <= '0;
      wdata_c <= '0;
      compute_done <= 1'b0;
    end else begin
      we_c <= 1'b0;
      compute_done <= 1'b0;

      if (!enable_compute) begin
        ph_q <= PH_BIAS_ISSUE;
        i_q <= '0;
        j_q <= '0;
        k_q <= '0;
        acc_q <= '0;
        raddr_a <= '0;
        raddr_b <= '0;
        raddr_bias <= '0;
      end else begin
        unique case (ph_q)
          PH_BIAS_ISSUE: begin
            raddr_bias <= j_q;
            ph_q <= PH_BIAS_CAPTURE;
          end
          PH_BIAS_CAPTURE: begin
            acc_q <= rdata_bias;
            k_q <= '0;
            ph_q <= PH_MAC_ISSUE;
          end
          PH_MAC_ISSUE: begin
            raddr_a <= a_addr_calc;
            raddr_b <= b_addr_calc;
            ph_q <= PH_MAC_UPDATE;
          end
          PH_MAC_UPDATE: begin
            a_hold_q <= rdata_a;
            b_hold_q <= rdata_b;
            acc_q <= sum32;
            if (k_q == K_FIXED-1) begin
              waddr_c <= c_addr_calc;
              wdata_c <= sum32[31] ? 32'sd0 : sum32;
              we_c <= 1'b1;
              if ((i_q == M_FIXED-1) && (j_q == N_FIXED-1)) begin
                compute_done <= 1'b1;
              end
              if (j_q == N_FIXED-1) begin
                j_q <= '0;
                i_q <= i_q + 1'b1;
              end else begin
                j_q <= j_q + 1'b1;
              end
              ph_q <= PH_BIAS_ISSUE;
            end else begin
              k_q <= k_q + 1'b1;
              ph_q <= PH_MAC_ISSUE;
            end
          end
          default: ph_q <= PH_BIAS_ISSUE;
        endcase
      end
    end
  end
endmodule

module output_streamer #(
  parameter int M_FIXED = 8,
  parameter int N_FIXED = 8,
  parameter int K_FIXED = 32
) (
  input  logic clk,
  input  logic rst_n,
  input  logic enable_output,
  input  logic out_ready,
  output logic out_valid,
  output logic signed [31:0] out_payload,
  output logic out_last,
  output logic out_hs,
  output logic [5:0] raddr_c,
  input  logic signed [31:0] rdata_c
);
  localparam int C_COUNT = M_FIXED*N_FIXED;
  logic [6:0] count_q;
  logic active_q;
  logic [5:0] addr_pipe_q;

  always_ff @(posedge clk) begin
    if (!rst_n) begin
      out_valid <= 1'b0;
      out_payload <= '0;
      out_last <= 1'b0;
      out_hs <= 1'b0;
      raddr_c <= '0;
      addr_pipe_q <= '0;
      count_q <= '0;
      active_q <= 1'b0;
    end else begin
      out_hs <= 1'b0;
      if (!enable_output) begin
        out_valid <= 1'b0;
        out_payload <= '0;
        out_last <= 1'b0;
        raddr_c <= '0;
        addr_pipe_q <= '0;
        count_q <= '0;
        active_q <= 1'b0;
      end else begin
        if (!active_q) begin
          raddr_c <= 6'd0;
          addr_pipe_q <= 6'd0;
          active_q <= 1'b1;
          count_q <= 7'd0;
        end

        if (!out_valid) begin
          out_valid <= 1'b1;
          out_payload <= rdata_c;
          out_last <= (count_q == C_COUNT-1);
        end else if (out_ready) begin
          out_hs <= 1'b1;
          if (count_q == C_COUNT-1) begin
            out_valid <= 1'b0;
            out_last <= 1'b0;
          end else begin
            count_q <= count_q + 1'b1;
            raddr_c <= count_q + 1'b1;
            addr_pipe_q <= count_q + 1'b1;
            out_payload <= rdata_c;
            out_last <= (count_q + 1'b1 == C_COUNT-1);
          end
        end
      end
    end
  end
endmodule

module gemm8x8x32_top #(
  parameter int M_FIXED = 8,
  parameter int N_FIXED = 8,
  parameter int K_FIXED = 32
) (
  input  logic clk,
  input  logic rst_n,
  input  logic cmd_valid,
  output logic cmd_ready,
  input  logic cmd_payload,
  input  logic a_valid,
  output logic a_ready,
  input  logic signed [7:0] a_payload,
  input  logic b_valid,
  output logic b_ready,
  input  logic signed [7:0] b_payload,
  input  logic bias_valid,
  output logic bias_ready,
  input  logic signed [31:0] bias_payload,
  output logic out_valid,
  input  logic out_ready,
  output logic signed [31:0] out_payload,
  output logic out_last,
  output logic busy,
  output logic completion,
  output logic error
);
  logic cmd_hs, a_hs, b_hs, bias_hs, out_hs;
  logic state_load_a, state_load_b, state_load_bias, state_compute, state_output;
  logic compute_done;

  logic we_a, we_b, we_bias;
  logic [7:0] waddr_a, waddr_b;
  logic [2:0] waddr_bias;

  logic [7:0] raddr_a, raddr_b;
  logic [2:0] raddr_bias;
  logic signed [7:0] rdata_a, rdata_b;
  logic signed [31:0] rdata_bias;

  logic we_c;
  logic [5:0] waddr_c, raddr_c;
  logic signed [31:0] wdata_c, rdata_c;

  logic [8:0] a_load_idx_q;
  logic [8:0] b_load_idx_q;
  logic [3:0] bias_load_idx_q;

  assign cmd_hs  = cmd_valid  & cmd_ready;
  assign a_hs    = a_valid    & a_ready;
  assign b_hs    = b_valid    & b_ready;
  assign bias_hs = bias_valid & bias_ready;

  assign we_a = a_hs;
  assign we_b = b_hs;
  assign we_bias = bias_hs;

  assign waddr_a = a_load_idx_q[7:0];
  assign waddr_b = b_load_idx_q[7:0];
  assign waddr_bias = bias_load_idx_q[2:0];

  always_ff @(posedge clk) begin
    if (!rst_n) begin
      a_load_idx_q <= '0;
      b_load_idx_q <= '0;
      bias_load_idx_q <= '0;
    end else begin
      if (!state_load_a) a_load_idx_q <= '0;
      else if (a_hs) a_load_idx_q <= a_load_idx_q + 1'b1;

      if (!state_load_b) b_load_idx_q <= '0;
      else if (b_hs) b_load_idx_q <= b_load_idx_q + 1'b1;

      if (!state_load_bias) bias_load_idx_q <= '0;
      else if (bias_hs) bias_load_idx_q <= bias_load_idx_q + 1'b1;
    end
  end

  gemm_ctrl_fsm #(.M_FIXED(M_FIXED), .N_FIXED(N_FIXED), .K_FIXED(K_FIXED)) u_ctrl (
    .clk(clk), .rst_n(rst_n), .cmd_hs(cmd_hs), .cmd_payload(cmd_payload), .a_hs(a_hs), .b_hs(b_hs), .bias_hs(bias_hs),
    .compute_done(compute_done), .out_hs(out_hs), .state_load_a(state_load_a), .state_load_b(state_load_b), .state_load_bias(state_load_bias),
    .state_compute(state_compute), .state_output(state_output), .cmd_ready(cmd_ready), .a_ready(a_ready), .b_ready(b_ready), .bias_ready(bias_ready),
    .busy(busy), .completion(completion), .error(error)
  );

  mac_sequencer #(.M_FIXED(M_FIXED), .N_FIXED(N_FIXED), .K_FIXED(K_FIXED)) u_mac (
    .clk(clk), .rst_n(rst_n), .enable_compute(state_compute), .raddr_a(raddr_a), .rdata_a(rdata_a), .raddr_b(raddr_b), .rdata_b(rdata_b),
    .raddr_bias(raddr_bias), .rdata_bias(rdata_bias), .we_c(we_c), .waddr_c(waddr_c), .wdata_c(wdata_c), .compute_done(compute_done)
  );

  output_streamer #(.M_FIXED(M_FIXED), .N_FIXED(N_FIXED), .K_FIXED(K_FIXED)) u_out (
    .clk(clk), .rst_n(rst_n), .enable_output(state_output), .out_ready(out_ready), .out_valid(out_valid), .out_payload(out_payload),
    .out_last(out_last), .out_hs(out_hs), .raddr_c(raddr_c), .rdata_c(rdata_c)
  );

  operand_buffer_bank #(.M_FIXED(M_FIXED), .N_FIXED(N_FIXED), .K_FIXED(K_FIXED)) u_buf (
    .clk(clk), .we_a(we_a), .waddr_a(waddr_a), .wdata_a(a_payload), .we_b(we_b), .waddr_b(waddr_b), .wdata_b(b_payload),
    .we_bias(we_bias), .waddr_bias(waddr_bias), .wdata_bias(bias_payload), .raddr_a(raddr_a), .rdata_a(rdata_a), .raddr_b(raddr_b), .rdata_b(rdata_b),
    .raddr_bias(raddr_bias), .rdata_bias(rdata_bias), .we_c(we_c), .waddr_c(waddr_c), .wdata_c(wdata_c), .raddr_c(raddr_c), .rdata_c(rdata_c)
  );
endmodule

module gemm_ctrl_fsm #(
  parameter int M_FIXED = 8,
  parameter int N_FIXED = 8,
  parameter int K_FIXED = 32
) (
  input  logic clk,
  input  logic rst_n,
  input  logic cmd_hs,
  input  logic cmd_payload,
  input  logic a_hs,
  input  logic b_hs,
  input  logic bias_hs,
  input  logic compute_done,
  input  logic out_hs,
  output logic state_load_a,
  output logic state_load_b,
  output logic state_load_bias,
  output logic state_compute,
  output logic state_output,
  output logic cmd_ready,
  output logic a_ready,
  output logic b_ready,
  output logic bias_ready,
  output logic busy,
  output logic completion,
  output logic error
);
  localparam int A_COUNT    = M_FIXED*K_FIXED;
  localparam int B_COUNT    = K_FIXED*N_FIXED;
  localparam int BIAS_COUNT = N_FIXED;
  localparam int C_COUNT    = M_FIXED*N_FIXED;

  localparam int AW_A    = (A_COUNT    <= 1) ? 1 : $clog2(A_COUNT+1);
  localparam int AW_B    = (B_COUNT    <= 1) ? 1 : $clog2(B_COUNT+1);
  localparam int AW_BIAS = (BIAS_COUNT <= 1) ? 1 : $clog2(BIAS_COUNT+1);
  localparam int AW_C    = (C_COUNT    <= 1) ? 1 : $clog2(C_COUNT+1);

  typedef enum logic [2:0] {
    ST_IDLE      = 3'd0,
    ST_LOAD_A    = 3'd1,
    ST_LOAD_B    = 3'd2,
    ST_LOAD_BIAS = 3'd3,
    ST_COMPUTE   = 3'd4,
    ST_OUTPUT    = 3'd5,
    ST_DONE      = 3'd6
  } state_t;

  state_t state_q, state_d;
  logic [AW_A-1:0]    a_count_q;
  logic [AW_B-1:0]    b_count_q;
  logic [AW_BIAS-1:0] bias_count_q;
  logic [AW_C-1:0]    out_count_q;

  always_comb begin
    state_load_a    = (state_q == ST_LOAD_A);
    state_load_b    = (state_q == ST_LOAD_B);
    state_load_bias = (state_q == ST_LOAD_BIAS);
    state_compute   = (state_q == ST_COMPUTE);
    state_output    = (state_q == ST_OUTPUT);

    cmd_ready  = rst_n && (state_q == ST_IDLE);
    a_ready    = rst_n && (state_q == ST_LOAD_A);
    b_ready    = rst_n && (state_q == ST_LOAD_B);
    bias_ready = rst_n && (state_q == ST_LOAD_BIAS);

    state_d = state_q;
    unique case (state_q)
      ST_IDLE:      if (cmd_hs && (cmd_payload == 1'b1)) state_d = ST_LOAD_A;
      ST_LOAD_A:    if (a_hs    && (a_count_q    == A_COUNT-1)) state_d = ST_LOAD_B;
      ST_LOAD_B:    if (b_hs    && (b_count_q    == B_COUNT-1)) state_d = ST_LOAD_BIAS;
      ST_LOAD_BIAS: if (bias_hs && (bias_count_q == BIAS_COUNT-1)) state_d = ST_COMPUTE;
      ST_COMPUTE:   if (compute_done) state_d = ST_OUTPUT;
      ST_OUTPUT:    if (out_hs && (out_count_q == C_COUNT-1)) state_d = ST_DONE;
      ST_DONE:      state_d = ST_IDLE;
      default:      state_d = ST_IDLE;
    endcase
  end

  always_ff @(posedge clk) begin
    if (!rst_n) begin
      state_q      <= ST_IDLE;
      a_count_q    <= '0;
      b_count_q    <= '0;
      bias_count_q <= '0;
      out_count_q  <= '0;
      busy         <= 1'b0;
      completion   <= 1'b0;
      error        <= 1'b0;
    end else begin
      state_q <= state_d;
      completion <= 1'b0;
      error <= 1'b0;

      if ((state_q == ST_IDLE) && cmd_hs && (cmd_payload == 1'b1)) busy <= 1'b1;
      if ((state_q == ST_OUTPUT) && out_hs && (out_count_q == C_COUNT-1)) busy <= 1'b0;
      if (state_q == ST_DONE) completion <= 1'b1;

      if (cmd_hs && ((state_q != ST_IDLE) || (cmd_payload != 1'b1))) error <= 1'b1;
      if (a_hs    && (state_q != ST_LOAD_A))    error <= 1'b1;
      if (b_hs    && (state_q != ST_LOAD_B))    error <= 1'b1;
      if (bias_hs && (state_q != ST_LOAD_BIAS)) error <= 1'b1;

      if (state_q != ST_LOAD_A) a_count_q <= '0;
      else if (a_hs) a_count_q <= a_count_q + 1'b1;

      if (state_q != ST_LOAD_B) b_count_q <= '0;
      else if (b_hs) b_count_q <= b_count_q + 1'b1;

      if (state_q != ST_LOAD_BIAS) bias_count_q <= '0;
      else if (bias_hs) bias_count_q <= bias_count_q + 1'b1;

      if (state_q != ST_OUTPUT) out_count_q <= '0;
      else if (out_hs) out_count_q <= out_count_q + 1'b1;
    end
  end
endmodule

module operand_buffer_bank #(
  parameter int M_FIXED = 8,
  parameter int N_FIXED = 8,
  parameter int K_FIXED = 32
) (
  input  logic                  clk,
  input  logic                  we_a,
  input  logic [7:0]            waddr_a,
  input  logic signed [7:0]     wdata_a,
  input  logic                  we_b,
  input  logic [7:0]            waddr_b,
  input  logic signed [7:0]     wdata_b,
  input  logic                  we_bias,
  input  logic [2:0]            waddr_bias,
  input  logic signed [31:0]    wdata_bias,
  input  logic [7:0]            raddr_a,
  output logic signed [7:0]     rdata_a,
  input  logic [7:0]            raddr_b,
  output logic signed [7:0]     rdata_b,
  input  logic [2:0]            raddr_bias,
  output logic signed [31:0]    rdata_bias,
  input  logic                  we_c,
  input  logic [5:0]            waddr_c,
  input  logic signed [31:0]    wdata_c,
  input  logic [5:0]            raddr_c,
  output logic signed [31:0]    rdata_c
);
  localparam int A_COUNT    = M_FIXED*K_FIXED;
  localparam int B_COUNT    = K_FIXED*N_FIXED;
  localparam int BIAS_COUNT = N_FIXED;
  localparam int C_COUNT    = M_FIXED*N_FIXED;

  logic signed [7:0]  a_buf [0:A_COUNT-1];
  logic signed [7:0]  b_buf [0:B_COUNT-1];
  logic signed [31:0] bias_buf [0:BIAS_COUNT-1];
  logic signed [31:0] c_buf [0:C_COUNT-1];

  always_ff @(posedge clk) begin
    if (we_a) a_buf[waddr_a] <= wdata_a;
    if (we_b) b_buf[waddr_b] <= wdata_b;
    if (we_bias) bias_buf[waddr_bias] <= wdata_bias;
    if (we_c) c_buf[waddr_c] <= wdata_c;

    rdata_a    <= a_buf[raddr_a];
    rdata_b    <= b_buf[raddr_b];
    rdata_bias <= bias_buf[raddr_bias];
    rdata_c    <= c_buf[raddr_c];
  end
endmodule

module mac_sequencer #(
  parameter int M_FIXED = 8,
  parameter int N_FIXED = 8,
  parameter int K_FIXED = 32
) (
  input  logic clk,
  input  logic rst_n,
  input  logic enable_compute,
  output logic [7:0] raddr_a,
  input  logic signed [7:0] rdata_a,
  output logic [7:0] raddr_b,
  input  logic signed [7:0] rdata_b,
  output logic [2:0] raddr_bias,
  input  logic signed [31:0] rdata_bias,
  output logic we_c,
  output logic [5:0] waddr_c,
  output logic signed [31:0] wdata_c,
  output logic compute_done
);
  typedef enum logic [1:0] {PH_BIAS_ISSUE=2'd0, PH_BIAS_CAPTURE=2'd1, PH_MAC_ISSUE=2'd2, PH_MAC_UPDATE=2'd3} ph_t;
  ph_t ph_q;

  logic [2:0] i_q, j_q;
  logic [5:0] k_q;
  logic signed [31:0] acc_q;
  logic signed [7:0] a_hold_q, b_hold_q;

  logic [7:0] a_addr_calc, b_addr_calc;
  logic [5:0] c_addr_calc;
  logic signed [15:0] prod16;
  logic signed [31:0] prod32;
  logic signed [31:0] sum32;

  always_comb begin
    a_addr_calc = (i_q * K_FIXED) + k_q;
    b_addr_calc = (k_q * N_FIXED) + j_q;
    c_addr_calc = (i_q * N_FIXED) + j_q;
    prod16 = a_hold_q * b_hold_q;
    prod32 = {{16{prod16[15]}}, prod16};
    sum32 = acc_q + prod32;
  end

  always_ff @(posedge clk) begin
    if (!rst_n) begin
      ph_q <= PH_BIAS_ISSUE;
      i_q <= '0;
      j_q <= '0;
      k_q <= '0;
      acc_q <= '0;
      a_hold_q <= '0;
      b_hold_q <= '0;
      raddr_a <= '0;
      raddr_b <= '0;
      raddr_bias <= '0;
      we_c <= 1'b0;
      waddr_c <= '0;
      wdata_c <= '0;
      compute_done <= 1'b0;
    end else begin
      we_c <= 1'b0;
      compute_done <= 1'b0;

      if (!enable_compute) begin
        ph_q <= PH_BIAS_ISSUE;
        i_q <= '0;
        j_q <= '0;
        k_q <= '0;
        acc_q <= '0;
        raddr_a <= '0;
        raddr_b <= '0;
        raddr_bias <= '0;
      end else begin
        unique case (ph_q)
          PH_BIAS_ISSUE: begin
            raddr_bias <= j_q;
            ph_q <= PH_BIAS_CAPTURE;
          end
          PH_BIAS_CAPTURE: begin
            acc_q <= rdata_bias;
            k_q <= '0;
            ph_q <= PH_MAC_ISSUE;
          end
          PH_MAC_ISSUE: begin
            raddr_a <= a_addr_calc;
            raddr_b <= b_addr_calc;
            ph_q <= PH_MAC_UPDATE;
          end
          PH_MAC_UPDATE: begin
            a_hold_q <= rdata_a;
            b_hold_q <= rdata_b;
            acc_q <= sum32;
            if (k_q == K_FIXED-1) begin
              waddr_c <= c_addr_calc;
              wdata_c <= sum32[31] ? 32'sd0 : sum32;
              we_c <= 1'b1;
              if ((i_q == M_FIXED-1) && (j_q == N_FIXED-1)) begin
                compute_done <= 1'b1;
              end
              if (j_q == N_FIXED-1) begin
                j_q <= '0;
                i_q <= i_q + 1'b1;
              end else begin
                j_q <= j_q + 1'b1;
              end
              ph_q <= PH_BIAS_ISSUE;
            end else begin
              k_q <= k_q + 1'b1;
              ph_q <= PH_MAC_ISSUE;
            end
          end
          default: ph_q <= PH_BIAS_ISSUE;
        endcase
      end
    end
  end
endmodule

module output_streamer #(
  parameter int M_FIXED = 8,
  parameter int N_FIXED = 8,
  parameter int K_FIXED = 32
) (
  input  logic clk,
  input  logic rst_n,
  input  logic enable_output,
  input  logic out_ready,
  output logic out_valid,
  output logic signed [31:0] out_payload,
  output logic out_last,
  output logic out_hs,
  output logic [5:0] raddr_c,
  input  logic signed [31:0] rdata_c
);
  localparam int C_COUNT = M_FIXED*N_FIXED;
  logic [6:0] count_q;
  logic active_q;
  logic [5:0] addr_pipe_q;

  always_ff @(posedge clk) begin
    if (!rst_n) begin
      out_valid <= 1'b0;
      out_payload <= '0;
      out_last <= 1'b0;
      out_hs <= 1'b0;
      raddr_c <= '0;
      addr_pipe_q <= '0;
      count_q <= '0;
      active_q <= 1'b0;
    end else begin
      out_hs <= 1'b0;
      if (!enable_output) begin
        out_valid <= 1'b0;
        out_payload <= '0;
        out_last <= 1'b0;
        raddr_c <= '0;
        addr_pipe_q <= '0;
        count_q <= '0;
        active_q <= 1'b0;
      end else begin
        if (!active_q) begin
          raddr_c <= 6'd0;
          addr_pipe_q <= 6'd0;
          active_q <= 1'b1;
          count_q <= 7'd0;
        end

        if (!out_valid) begin
          out_valid <= 1'b1;
          out_payload <= rdata_c;
          out_last <= (count_q == C_COUNT-1);
        end else if (out_ready) begin
          out_hs <= 1'b1;
          if (count_q == C_COUNT-1) begin
            out_valid <= 1'b0;
            out_last <= 1'b0;
          end else begin
            count_q <= count_q + 1'b1;
            raddr_c <= count_q + 1'b1;
            addr_pipe_q <= count_q + 1'b1;
            out_payload <= rdata_c;
            out_last <= (count_q + 1'b1 == C_COUNT-1);
          end
        end
      end
    end
  end
endmodule

module gemm8x8x32_top #(
  parameter int M_FIXED = 8,
  parameter int N_FIXED = 8,
  parameter int K_FIXED = 32
) (
  input  logic clk,
  input  logic rst_n,
  input  logic cmd_valid,
  output logic cmd_ready,
  input  logic cmd_payload,
  input  logic a_valid,
  output logic a_ready,
  input  logic signed [7:0] a_payload,
  input  logic b_valid,
  output logic b_ready,
  input  logic signed [7:0] b_payload,
  input  logic bias_valid,
  output logic bias_ready,
  input  logic signed [31:0] bias_payload,
  output logic out_valid,
  input  logic out_ready,
  output logic signed [31:0] out_payload,
  output logic out_last,
  output logic busy,
  output logic completion,
  output logic error
);
  logic cmd_hs, a_hs, b_hs, bias_hs, out_hs;
  logic state_load_a, state_load_b, state_load_bias, state_compute, state_output;
  logic compute_done;

  logic we_a, we_b, we_bias;
  logic [7:0] waddr_a, waddr_b;
  logic [2:0] waddr_bias;

  logic [7:0] raddr_a, raddr_b;
  logic [2:0] raddr_bias;
  logic signed [7:0] rdata_a, rdata_b;
  logic signed [31:0] rdata_bias;

  logic we_c;
  logic [5:0] waddr_c, raddr_c;
  logic signed [31:0] wdata_c, rdata_c;

  logic [8:0] a_load_idx_q;
  logic [8:0] b_load_idx_q;
  logic [3:0] bias_load_idx_q;

  assign cmd_hs  = cmd_valid  & cmd_ready;
  assign a_hs    = a_valid    & a_ready;
  assign b_hs    = b_valid    & b_ready;
  assign bias_hs = bias_valid & bias_ready;

  assign we_a = a_hs;
  assign we_b = b_hs;
  assign we_bias = bias_hs;

  assign waddr_a = a_load_idx_q[7:0];
  assign waddr_b = b_load_idx_q[7:0];
  assign waddr_bias = bias_load_idx_q[2:0];

  always_ff @(posedge clk) begin
    if (!rst_n) begin
      a_load_idx_q <= '0;
      b_load_idx_q <= '0;
      bias_load_idx_q <= '0;
    end else begin
      if (!state_load_a) a_load_idx_q <= '0;
      else if (a_hs) a_load_idx_q <= a_load_idx_q + 1'b1;

      if (!state_load_b) b_load_idx_q <= '0;
      else if (b_hs) b_load_idx_q <= b_load_idx_q + 1'b1;

      if (!state_load_bias) bias_load_idx_q <= '0;
      else if (bias_hs) bias_load_idx_q <= bias_load_idx_q + 1'b1;
    end
  end

  gemm_ctrl_fsm #(.M_FIXED(M_FIXED), .N_FIXED(N_FIXED), .K_FIXED(K_FIXED)) u_ctrl (
    .clk(clk), .rst_n(rst_n), .cmd_hs(cmd_hs), .cmd_payload(cmd_payload), .a_hs(a_hs), .b_hs(b_hs), .bias_hs(bias_hs),
    .compute_done(compute_done), .out_hs(out_hs), .state_load_a(state_load_a), .state_load_b(state_load_b), .state_load_bias(state_load_bias),
    .state_compute(state_compute), .state_output(state_output), .cmd_ready(cmd_ready), .a_ready(a_ready), .b_ready(b_ready), .bias_ready(bias_ready),
    .busy(busy), .completion(completion), .error(error)
  );

  mac_sequencer #(.M_FIXED(M_FIXED), .N_FIXED(N_FIXED), .K_FIXED(K_FIXED)) u_mac (
    .clk(clk), .rst_n(rst_n), .enable_compute(state_compute), .raddr_a(raddr_a), .rdata_a(rdata_a), .raddr_b(raddr_b), .rdata_b(rdata_b),
    .raddr_bias(raddr_bias), .rdata_bias(rdata_bias), .we_c(we_c), .waddr_c(waddr_c), .wdata_c(wdata_c), .compute_done(compute_done)
  );

  output_streamer #(.M_FIXED(M_FIXED), .N_FIXED(N_FIXED), .K_FIXED(K_FIXED)) u_out (
    .clk(clk), .rst_n(rst_n), .enable_output(state_output), .out_ready(out_ready), .out_valid(out_valid), .out_payload(out_payload),
    .out_last(out_last), .out_hs(out_hs), .raddr_c(raddr_c), .rdata_c(rdata_c)
  );

  operand_buffer_bank #(.M_FIXED(M_FIXED), .N_FIXED(N_FIXED), .K_FIXED(K_FIXED)) u_buf (
    .clk(clk), .we_a(we_a), .waddr_a(waddr_a), .wdata_a(a_payload), .we_b(we_b), .waddr_b(waddr_b), .wdata_b(b_payload),
    .we_bias(we_bias), .waddr_bias(waddr_bias), .wdata_bias(bias_payload), .raddr_a(raddr_a), .rdata_a(rdata_a), .raddr_b(raddr_b), .rdata_b(rdata_b),
    .raddr_bias(raddr_bias), .rdata_bias(rdata_bias), .we_c(we_c), .waddr_c(waddr_c), .wdata_c(wdata_c), .raddr_c(raddr_c), .rdata_c(rdata_c)
  );
endmodule
